SELECT FROM notification_logs WHERE deleted = 0
AND business_type = #{businessType}
ORDER BY create_time DESC

SELECT 
FROM notification_logs
WHERE deleted = 0
AND create_time >= #{startTime}
AND create_time <= #{endTime}
ORDER BY create_time DESC

SELECT FROM notification_logs WHERE deleted = 0
AND channel = #{channel}
AND business_type = #{businessType}
AND create_time >= TO_TIMESTAMP(#{startDate} || ' 00:00:00', 'YYYY-MM-DD HH24:MI:SS')
AND create_time <= TO_TIMESTAMP(#{endDate} || ' 23:59:59', 'YYYY-MM-DD HH24:MI:SS')
ORDER BY create_time DESC
